        } else {
            self.delay = Some(Box::pin(sleep_until(delay_time)));
        }
    }

    fn reset_delay_to(&mut self, deadline: Instant) {
        if let Some(ref mut delay) = &mut self.delay {
            delay.as_mut().reset(deadline);
        }
    }

    fn delay_is_elapsed(&self) -> bool {
        match self.delay.as_ref() {
            Some(delay) => delay.is_elapsed(),
            None => false,
        }
    }

    fn origin_instant(&self) -> Instant {
        self.start
    }

    fn instant_from_millis(&self, when: u64) -> Instant {
        if when == 0 {
            self.origin_instant()
        } else {
            self.origin_instant() + Duration::from_millis(when)
        }
    }

