                when - self.start,
                if round_up {
                    crate::time::Round::Up
                } else {
                    crate::time::Round::Down
                },
            )
        }
    }

    fn recorded_wheel_now(&self) -> u64 {
        self.wheel_now
    }

    fn set_recorded_wheel_now(&mut self, now: u64) {
