        let slot = self.slot_for_owned_deadline(when, level);
        self.wheel.levels[level].slot[slot].push(key, &mut self.slab);
        let bit = 1u64 << slot;
        self.wheel.levels[level].occupied |= bit;
    }

    fn remove_entry_at_level(&mut self, level: usize, when: u64, key: &Key) {
        use crate::time::wheel::Stack as WheelStack;
        let slot = self.slot_for_owned_deadline(when, level);
        self.wheel.levels[level].slot[slot].remove(key, &mut self.slab);
        if self.wheel.levels[level].slot[slot].is_empty() {
            let bit = 1u64 << slot;
            if self.wheel.levels[level].occupied & bit != 0 {
                self.wheel.levels[level].occupied ^= bit;
            }
        }
    }

