        use crate::time::wheel::Stack as WheelStack;
        let ret = self.wheel.levels[level].slot[slot].pop(&mut self.slab);
        if ret.is_some() && self.wheel.levels[level].slot[slot].is_empty() {
            let bit = 1u64 << slot;
            if self.wheel.levels[level].occupied & bit != 0 {
                self.wheel.levels[level].occupied ^= bit;
            }
        }
        ret
